    system:'<rect x="3" y="3" width="18" height="18" rx="4"/><rect x="7" y="7" width="10" height="10" rx="2"/><path d="M8 1v2M12 1v2M16 1v2M8 21v2M12 21v2M16 21v2M1 8h2M1 12h2M1 16h2M21 8h2M21 12h2M21 16h2"/>',
