    wifi:'<path d="M3 9a14 14 0 0118 0M6 13a9 9 0 0112 0M9 16a5 5 0 016 0"/><circle cx="12" cy="19" r=".8"/>',
    plus:'<path d="M12 4v16M4 12h16"/>', close:'<path d="M5 5l14 14M19 5L5 19"/>', minimize:'<path d="M5 17h14"/>', maximize:'<rect x="5" y="5" width="14" height="14" rx="1"/>',
    project:'<path d="M8 8V4h13v12h-5M3 8h13v13H3z"/><path d="M6 12h6M9 9v6"/>',
    play:'<path d="M8 5l11 7-11 7z"/>', pause:'<path d="M7 5h4v14H7zM15 5h4v14h-4z"/>', stop:'<rect x="6" y="6" width="12" height="12" rx="1"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
