    arrow:'<path d="M5 12h14M13 6l6 6-6 6"/>', check:'<path d="M4 12l5 5L20 6"/>', warning:'<path d="M12 3l10 18H2z"/><path d="M12 9v5M12 17h.01"/>',
    refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M19 12a7 7 0 00-12-5M5 12a7 7 0 0012 5"/>',
